{
  "name": "recorded-test",
  "version": "1.0.0",
  "private": true,
  "description": "Playwright tests for Recorded Test",
  "scripts": {
    "test": "npx playwright test",
    "test:headed": "npx playwright test --headed",
    "test:ui": "npx playwright test --ui",
    "report": "npx playwright show-report"
  },
  "devDependencies": {
    "@playwright/test": "^1.52.0"
  }
}

import { defineConfig, devices } from '@playwright/test';

/**
 * Playwright configuration for Recorded Test.
 * Generated by CmdRunner from the Execution IR.
 */
export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: 'html',
  use: {
    baseURL: 'chrome-extension://gndjidfncanlhlonpcabokbdhnikglpn/src/sidepanel/index.html',
    viewport: { width: 780, height: 437 },
    trace: 'on-first-retry',
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],
});

import { test, expect } from '@playwright/test';

test.describe('Recorded Test', () => {
  test('should complete recorded Test successfully', async ({ page }) => {
    // Select Choose Saturday, September 5th, 2026 in the Depart on
    await page.locator('[data-auto-id="depart-on"]').fill('Choose Saturday, September 5th, 2026')
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('0')
    await expect.soft(page.locator('#app-root')).toContainText('02h 30m')
    await expect.soft(page.locator('[data-sku="MEAL"]')).toBeAttached()

    // Click the 02h 30m
    await page.locator('[data-auto-id="duration-under-2h"]').click()
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('0')
    await expect.soft(page.locator('#app-root')).toContainText('02h 30m')
    await expect.soft(page.locator('[data-sku="MEAL"]')).toBeAttached()

    // Click the Select flight QP-1478
    await page.locator('[data-auto-id="flight-F3"]').click()
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('2')
    await expect.soft(page.locator('#app-root')).toContainText('02h 30m')
    await expect.soft(page.locator('[data-sku="MEAL"]')).toBeAttached()
  });
});
